SELECT id, activity_id, user_id, status, submitted_at, cancelled_at, invalidated_at, invalidated_by, invalid_reason
FROM activity_registration WHERE activity_id = #{activityId}
AND status = #{status}
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}

SELECT id, activity_id, user_id, status, form_data, submitted_at, cancelled_at,
       invalidated_at, invalidated_by, invalid_reason, created_at, updated_at
FROM activity_registration WHERE activity_id = #{activityId}
AND status = #{status}
ORDER BY id DESC LIMIT #{limit}
